#!/usr/bin/env python3
"""Wave-37h single-lane candidate (generated by gen_wave37h.py)."""
import numpy as np

M64 = (1 << 64) - 1
SCHED = [(26, 35, [18, 52, 2]), (56, 26, [60, 42, 19]), (62, 50, [33, 45, 11]), (3, 41, [47, 14, 54]), (29, 26, [59, 23, 62])]


def _rotl(v, r):
    r &= 63
    if r == 0:
        return v & M64
    return ((v << r) | (v >> (64 - r))) & M64


def mix(xs, k):
    xs = np.asarray(xs, dtype=np.uint64)
    k = np.asarray(k, dtype=np.uint64)
    x = (xs ^ k) & M64
    for a, b, lins in SCHED:
        v = x ^ (_rotl(x, a) & _rotl(x, b))
        for c in lins:
            v ^= _rotl(x, c)
        x = v & M64
    return (x ^ _rotl(k, 13)) & M64
